"""Scripted OpenAI-compatible mock. Responses are scripted, NOT generated by Qwen."""

import json

import httpx

from hive_exec.config import QwenSettings
from hive_exec.planner.qwen import QwenPlanner

MOCK_MODEL = "hive-mock/scripted-qwen"  # never labeled as live Qwen3-8B


class ScriptedQwen:
    """OpenAI-compatible mock for tests. Responses are scripted, NOT generated by Qwen."""

    def __init__(self, contents: list[str], model: str = MOCK_MODEL):
        self.contents = list(contents)
        self.model = model
        self.requests: list[dict] = []

    def handler(self, request: httpx.Request) -> httpx.Response:
        if request.url.path.endswith("/models"):
            return httpx.Response(200, json={"data": [{"id": self.model}]})
        body = json.loads(request.content)
        self.requests.append(body)
        if "Fly the drone to the roof" in body["messages"][-1]["content"]:  # probe
            content = json.dumps({"schema_version": "hive.plan-proposal.v1", "disposition": "reject", "scope": None,
                                  "summary": "No flight skill.", "mission_goals": [], "stage_goals": [], "tasks": [],
                                  "issues": [], "clarification_question": None})
        else:
            content = self.contents.pop(0)
        return httpx.Response(200, json={"model": self.model, "choices": [
            {"message": {"role": "assistant", "content": content}, "finish_reason": "stop"}],
            "usage": {"prompt_tokens": 100, "completion_tokens": 50}})


def scripted_planner(contents: list[str]) -> tuple[QwenPlanner, ScriptedQwen]:
    mock = ScriptedQwen(contents)
    planner = QwenPlanner(QwenSettings(base_url="http://mock.invalid/v1", model=MOCK_MODEL),
                          transport=httpx.MockTransport(mock.handler))
    return planner, mock
